const $=selector=>document.querySelector(selector);
const AI_LEVEL_NAMES={easy:'入门',casual:'休闲',advanced:'进阶',serious:'认真'};
const AI_LEVEL_NOTES={easy:'会漏看威胁，适合第一次下。',casual:'保持现在的陪练棋力。',advanced:'会补看吃子变化，少送子。',serious:'多想一层，最长约 0.2 秒；仍不是比赛级引擎。'};
const games={
  xiangqi:{name:'中国象棋',english:'XIANGQI',description:'楚河汉界，落子自有山河。',time:'10–30 分钟',tag:'国粹',category:'strategy',rules:'红方先行，双方轮流走子。车走直线，马走日且不能蹩腿，相（象）走田且不能塞眼、不能过河，仕（士）与帅（将）不能出九宫；炮吃子必须隔一子，兵（卒）过河后可以横走，不能后退。不得让己方被将军或将帅照面。将死或使对方无合法走法（困毙）均获胜。本休闲版中单方长将导致三次重复判负，其他三次重复判和；连续 120 手未吃子或双方无进攻子力判和。复杂长捉和比赛裁决暂不支持。电脑棋力可在入门、休闲、进阶、认真四档间切换；认真档会限时加深搜索，仍不是比赛级引擎。',instruction:'先选红方棋子，再点击标记的合法交叉点'},
  go:{name:'围棋',english:'GO · 9×9',description:'九路小棋盘，围出你的一片天地。',time:'10–20 分钟',tag:'国粹',category:'strategy',rules:'黑方先行，双方轮流在交叉点落子。棋子的气是相邻的空点，一块棋的气被堵光就会被提走。不能下在没有气又提不了子的点（禁着点），也不能让全局回到出现过的局面（打劫）。不想下时可以停一手，双方连续停一手后进入数子：棋子加围住的空点就是得数，黑方贴 7.5 目。数子时电脑或双方先标出死子，不同意可以继续对局，把棋走清楚。本版采用中国规则的数子法，只提供 9 路棋盘，电脑定位休闲陪练。',instruction:'点击交叉点落子'},
  gomoku:{name:'五子棋',english:'GOMOKU',description:'黑白之间，连成你的五子一线。',time:'5–15 分钟',tag:'经典',category:'strategy',rules:'黑方先行，双方轮流在交叉点落子。任意横、竖或斜线上，率先连成五子或更多的一方获胜。本版本采用自由五子棋规则，不设禁手。电脑棋力可在入门、休闲、进阶、认真四档间切换；认真档会限时加深搜索，仍不是比赛级引擎。',instruction:'点击棋盘交叉点落子'},
  chess:{name:'国际象棋',english:'CHESS',description:'六十四格，装得下无限可能。',time:'10–30 分钟',tag:'策略',category:'strategy',rules:'白方先行。先点击己方棋子，再点击标记的合法位置。将死对方国王即获胜；无合法走法但未被将军时为逼和。支持王车易位、吃过路兵及三次重复等和棋判定，兵升变时可选择后、车、象或马。电脑棋力可在入门、休闲、进阶、认真四档间切换；认真档会限时加深搜索，仍不是比赛级引擎。',instruction:'点击棋子，查看可走的位置'},
  reversi:{name:'黑白棋',english:'REVERSI',description:'一次翻转，让局势悄然改变。',time:'5–15 分钟',tag:'巧思',category:'strategy',rules:'黑方先行。落子后，沿横、竖或斜线夹住对方棋子，即可将它们翻为己方颜色；每手至少翻转一子。没有合法落点时自动跳过，双方均无法落子时结束，棋子更多者获胜。',instruction:'小圆点标记了你的合法落点'},
  tictactoe:{name:'井字棋',english:'TIC-TAC-TOE',description:'三横三竖，也有小小的博弈。',time:'1–3 分钟',tag:'轻松',category:'quick',rules:'叉号先行，双方轮流在空格内落子。横、竖或斜线上率先连成三个相同符号即获胜。棋盘填满而无人连线时为平局。电脑会认真应对，试着与它打成平手吧。',instruction:'点击空格，连成三个相同符号'},
  connect4:{name:'四子棋',english:'CONNECT FOUR',description:'棋子落下，四子一线定胜负。',time:'3–10 分钟',tag:'轻松',category:'quick',rules:'红方先行，双方轮流选择一列落子，棋子会落到该列最低的空位。横、竖或斜线上率先连成四子的一方获胜；棋盘下满而无人连线时为平局。电脑采用七层搜索，定位休闲陪练。',instruction:'点击任意一列，棋子会落到最低的空位'},
  tiaoqi:{name:'中国跳棋',english:'CHINESE CHECKERS',description:'借子连跳，抢先走进对面星角。',time:'10–20 分钟',tag:'亲子',category:'strategy',rules:'两人对局，各有十枚棋子，红方先行。每次可以走到相邻的空位；也可以跳过一枚相邻的棋子，落到它正后方的空位，双方的棋子都能当跳板，被跳的棋子不会被吃。一次可以连跳多次，随时停下，但走一步和跳不能混用。先让对面星角被占满且其中至少有一枚己方棋子的一方获胜，所以赖在自己家里不走也挡不住对手。同局面三次重复或双方合计 400 手未分胜负时判和。电脑采用四层搜索，定位休闲陪练。',instruction:'先选己方棋子，再点击标记的落点；连跳直接点最后的落点'},
  jungle:{name:'斗兽棋',english:'JUNGLE',description:'鼠能克象，步步走向对方兽穴。',time:'5–20 分钟',tag:'亲子',category:'strategy',rules:'红方先行，每次把一只动物沿横竖走一格。大小依次为象、狮、虎、豹、狼、狗、猫、鼠，可吃同级或更小的动物；鼠可吃象，象不能吃鼠。只有鼠能下河；河里的鼠不能被岸上的动物吃，也不能吃岸上的动物。狮和虎可以横竖跳过河，途中有鼠挡路时不能跳。走进对方陷阱的动物等级降为 0，任何对方动物都能吃它，它也吃不了别人。不能进入己方兽穴。走进对方兽穴、吃光对方动物或使对方无子可动即获胜。本休闲版约定：同局面三次重复或连续 100 手未吃子判和。各地规则略有差异，例如老虎能否横跳。',instruction:'先选己方动物，再点击标记的格子'},
  rubik:{name:'魔方 · 方寸解锁',english:'RUBIK’S CUBE',description:'转动六面色彩，解开一枚立体机关。',time:'3–10 分钟',tag:'3D 解谜',category:'quick',rules:'拖动魔方可环绕观察。用 U、D、L、R、F、B 分别转动上、下、左、右、前、后层；每个面都可顺时针或逆时针旋转。将六面颜色各自归一即可解锁。新局会打乱 18 步，可随时撤销自己的转动。',instruction:'拖动旋转视角，转动各面让颜色归位'},
  luban:{name:'鲁班锁 · 六销拆解',english:'LUBAN LOCK',description:'观察榫卯咬合，依序抽出六根木销。',time:'3–8 分钟',tag:'3D 解谜',category:'quick',rules:'拖动木锁环绕观察，也可点击木销名称选择构件。用方向按钮尝试抽出。卡住的木销会回弹；依序取出六根榫木即可解开机关。',instruction:'选一根木销，再尝试抽出方向'}
};
Object.entries(puzzleGames).forEach(([id,g])=>games[id]={...g,time:'3–15 分钟',tag:'益智',category:'quick'});
const STORAGE_KEY='chess-cheers-v1';
let endgameLib=null;
let store={saves:{},archives:[],sound:false,puzzleSolved:false,effects:true,aiLevels:{gomoku:'casual',xiangqi:'casual',chess:'casual'},appearance:{view:'3d',theme:'classic',angle:48,rotation:-12,zoom:1.5,version:2}};
let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(saved&&typeof saved==='object'){store={...store,...saved,saves:saved.saves&&typeof saved.saves==='object'?saved.saves:{},archives:Array.isArray(saved.archives)?saved.archives.slice(0,30):[]};}}catch{storageAvailable=false;}
let current=null,botTimer=null,session=0,toastTimer=null,dialogAction=null,promotionResolve=null;
let audioContext=null;
store.appearance={view:'3d',theme:'classic',angle:48,rotation:-12,...store.appearance};
if(store.appearance.version!==2)Object.assign(store.appearance,{view:'3d',angle:48,rotation:-12,version:2});
if(!['2d','3d'].includes(store.appearance.view))store.appearance.view='2d';
if(!boardThemes[store.appearance.theme])store.appearance.theme='classic';
store.appearance.angle=Math.max(15,Math.min(65,Number(store.appearance.angle)||48));
store.appearance.rotation=Number.isFinite(Number(store.appearance.rotation))?Number(store.appearance.rotation):-5;
store.appearance.zoom=Math.max(1,Math.min(1.5,Number(store.appearance.zoom)||1.5));
store.aiLevels={...(store.aiLevels&&typeof store.aiLevels==='object'&&!Array.isArray(store.aiLevels)?store.aiLevels:{})};
for(const kind of AI_LEVEL_KINDS)if(!isAiLevel(store.aiLevels[kind]))store.aiLevels[kind]='casual';
const effects=new GameEffects($('#board-stage'),()=>store.effects!==false);
effects.reduced.addEventListener('change',()=>{effects.clear();scene3d?.resetEffects();});
let scene3d=null,scenePromise=null,sceneFailed=false,victoryTimer=null,previewTimer=null,rubikScene=null,rubikPromise=null,lubanScene=null,lubanPromise=null;
function syncScene(){if(!scene3d||!current||store.appearance.view!=='3d'||$('#play-view').hidden)return;const board=$('#board'),marks=[...board.querySelectorAll('.selected,.legal,.last-move,.winning')].map(cell=>({r:cell.dataset.square?8-Number(cell.dataset.square[1]):Number(cell.dataset.r),c:cell.dataset.square?cell.dataset.square.charCodeAt(0)-97:Number(cell.dataset.c),type:cell.classList.contains('selected')?'selected':cell.classList.contains('legal')?'legal':'last'}));scene3d.sync({kind:current.kind,theme:store.appearance.theme,board:current.kind==='chess'?current.engine.board():current.kind==='go'?goSceneBoard():current.engine.board,marks});}
async function ensureScene(){if(sceneFailed){fallback3d();return;}if(!scenePromise){$('.scene-loading').hidden=false;scenePromise=import('./board3d.js').then(({Board3D})=>{scene3d=new Board3D($('#board-3d'),(r,c)=>{const selector=current?.kind==='chess'?`[data-square="${'abcdefgh'[c]}${8-r}"]`:`.board-cell[data-r="${r}"][data-c="${c}"]`;$(selector)?.click();},(angle,rotation)=>{store.appearance.angle=Math.round(angle);store.appearance.rotation=rotation;$('#board-angle').value=Math.round(angle);$('#angle-output').textContent=Math.round(angle)+'°';persist();},fallback3d);return scene3d;}).catch(fallback3d).finally(()=>{$('.scene-loading').hidden=true;});}await scenePromise;if(scene3d){const active=store.appearance.view==='3d'&&!$('#play-view').hidden;scene3d.setActive(active);if(active){scene3d.setCamera(store.appearance.angle,store.appearance.rotation);syncScene();}}}
function fallback3d(){sceneFailed=true;store.appearance.view='2d';applyAppearance();persist();toast('此设备暂时无法显示三维棋盘，已切回 2D。');}
function stopEffects(){clearTimeout(victoryTimer);clearTimeout(previewTimer);effects.clear();scene3d?.resetEffects();if($('#victory-dialog').open)$('#victory-dialog').close();}
function updateEffectsButton(){$('#effects-toggle').setAttribute('aria-pressed',String(store.effects!==false));$('#effects-state').textContent=store.effects!==false?'已开':'已关';}
$('#effects-toggle').addEventListener('click',()=>{store.effects=store.effects===false;stopEffects();persist();updateEffectsButton();toast(store.effects?'动态特效已开启':'动态特效已关闭');});
function showVictory(preview=false){if(!current)return;const result=winner(),won=preview||(result!==0&&(current.mode==='local'||result===1));$('#victory-secret').hidden=true;$('#victory-trophy').hidden=!won;$('#victory-eyebrow').textContent=preview?'EFFECT PREVIEW · 特效预览':current.puzzle?'PUZZLE COMPLETE · 棋题解锁':'A MOMENT WORTH CHEERING';$('#victory-title').textContent=preview?'这一局，值得举杯。':result===0?'不分胜负，亦是好棋。':won?(current.puzzle?'漂亮，一步将杀！':colorName(result)+'获胜，值得举杯。'):'棋友获胜，下局再会。';$('#victory-description').textContent=preview?'这是庆祝效果预览，不影响当前棋局和胜负记录。':won?'落子有声，思考有光。送你一枚属于这一局的奖杯。':'把这一局的思考，带进下一局。';$('#victory-rematch').textContent=preview?'继续当前对局':'再来一局 ↗';$('#victory-rematch').dataset.preview=String(preview);if(!$('#victory-dialog').open)$('#victory-dialog').showModal();$('#victory-dialog').append(effects.canvas);if(won){effects.confetti();if(effects.motion&&store.appearance.view==='3d')scene3d?.celebrate();}if(!preview)playSound('victory');}
function closeVictory(){effects.clear();scene3d?.resetEffects();$('#victory-dialog').close();}
$('#victory-close').addEventListener('click',closeVictory);$('#victory-review').addEventListener('click',closeVictory);$('#victory-dialog').addEventListener('cancel',()=>{effects.clear();scene3d?.resetEffects();});
$('#victory-rematch').addEventListener('click',()=>{const preview=$('#victory-rematch').dataset.preview==='true';closeVictory();if(!preview)replaceGame();});
$('#victory-trophy').addEventListener('click',()=>{$('#victory-secret').hidden=false;$('#victory-trophy').hidden=true;$('#victory-description').textContent='你发现了奖杯里的秘密。';effects.confetti();playSound('secret');});
$('#effects-preview').addEventListener('click',()=>{stopEffects();if(effects.motion){effects.impact(store.appearance.view==='3d','吃子反馈 · 预览');if(store.appearance.view==='3d'){scene3d?.shake();scene3d?.burst(current?.kind==='gomoku'?7:current?.kind==='tictactoe'?1:3,current?.kind==='gomoku'?7:current?.kind==='tictactoe'?1:4);}playSound('capture');}previewTimer=setTimeout(()=>showVictory(true),900);});
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(store));return true;}catch{if(storageAvailable){toast('当前浏览器无法保存进度，请及时导出棋谱。');storageAvailable=false;}return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function showDialog(title,body,action='知道了',callback=null){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog-action').textContent=action;dialogAction=callback;if(!$('#info-dialog').open)$('#info-dialog').showModal();}
function closeDialog(){if(promotionResolve){promotionResolve(null);promotionResolve=null;}$('#info-dialog').close();dialogAction=null;}
$('#dialog-close').addEventListener('click',closeDialog);
$('#info-dialog').addEventListener('cancel',()=>{if(promotionResolve){promotionResolve(null);promotionResolve=null;}dialogAction=null;});
$('#dialog-action').addEventListener('click',()=>{const callback=dialogAction;closeDialog();callback?.();});
$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
function playSound(kind='move'){if(!store.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const notes=kind==='victory'?[523,659,784,1047]:kind==='secret'?[784,988,1175]:kind==='capture'?[170,90]:[540];notes.forEach((frequency,i)=>{const time=audioContext.currentTime+i*.1,oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=kind==='capture'?'triangle':'sine';oscillator.frequency.setValueAtTime(frequency,time);oscillator.frequency.exponentialRampToValueAtTime(kind==='move'?180:frequency*.95,time+.13);gain.gain.setValueAtTime(.07,time);gain.gain.exponentialRampToValueAtTime(.001,time+.22);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(time);oscillator.stop(time+.23);});}catch{/* Audio is optional. */}}
function updateSound(){const button=$('#sound-button');button.querySelector('span:last-child').textContent=`落子音效已${store.sound?'开':'关'}`;button.setAttribute('aria-pressed',String(store.sound));}
$('#sound-button').addEventListener('click',()=>{store.sound=!store.sound;persist();updateSound();playSound();toast(`落子音效已${store.sound?'开启':'关闭'}`);});
$('#about-button').addEventListener('click',()=>showDialog('给好棋，留一点时间。','<p>弈间 · Chess & Cheers，是一个安静、轻盈的棋类空间。我们相信，好的对弈从好奇开始，也可以在一杯茶的时间里发生。</p><p>九种棋类支持本地双人与休闲人机；另有三阶魔方、鲁班锁，以及华容道、推箱子、七巧板、数织、数独和河内塔。棋谱只保存在当前浏览器；清除浏览器数据会移除记录，可提前导出留存。</p><p>当前版本无需登录，不提供远程联机。国际象棋规则由 chess.js 1.4.0 驱动。</p>'));

const tutorialRoom=new TutorialRoom();
document.addEventListener('click',event=>{const button=event.target.closest('[data-tutorial]');if(!button)return;const kind=button.dataset.tutorial==='current'?current?.kind:button.dataset.tutorial;if(!games[kind])return;cancelBot();tutorialRoom.open(kind,games[kind].rules);});
tutorialRoom.dialog.addEventListener('close',()=>{if(!$('#home-view').hidden)renderCards(document.querySelector('[data-filter].selected')?.dataset.filter||'chess');if(current&&!$('#play-view').hidden)scheduleBot();});
function renderCards(filter='chess'){const puzzle=filter==='puzzle';$('#collection-title').textContent=puzzle?'益智解谜':'棋类对弈';$('#collection-description').textContent=puzzle?'八款空间与逻辑小作，留一点时间给好奇心。':'九种经典棋类，邀棋友落座，认真下一局。';$('#game-grid').dataset.collection=filter;$('#game-grid').innerHTML=Object.entries(games).filter(([kind])=>(kind==='rubik'||kind==='luban'||!!puzzleGames[kind])===puzzle).map(([kind,g],index)=>`<article class="game-card"><button class="card-art ${kind}" data-play="${kind}" aria-label="开始${g.name}"><span class="game-number">${String(index+1).padStart(2,'0')} /</span>${puzzleGames[kind]?puzzleArt(kind):cardArt(kind)}</button><div class="card-body"><h3>${g.name}</h3><span class="english">${g.english}</span><p>${g.description}</p><div class="card-bottom"><span><span class="card-tag">${g.tag}</span>${g.time}</span>${icon('arrow')}</div><div class="card-learning-actions"><button data-tutorial="${kind}">${tutorialRoom.isCompleted(kind)?'复习教程 ✓':'教程与教学'}</button>${kind==='xiangqi'?'<button data-endgame>经典残局</button>':''}<button data-play="${kind}">开始游戏 ↗</button></div></div></article>`).join('');}
function cancelBot(){clearTimeout(botTimer);botTimer=null;session++;stopEffects();if(current)current.thinking=false;}
function showView(view){for(const key of ['home','records','play','unlock','luban','mind'])$(`#${key}-view`).hidden=key!==view;scene3d?.setActive(view==='play'&&store.appearance.view==='3d');rubikScene?.setActive(view==='unlock');lubanScene?.setActive(view==='luban');document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===view));$('#breadcrumb-current').textContent=view==='mind'?'益智小作':view==='home'?'游戏大厅':view==='records'?'我的棋谱':view==='unlock'?'3D 解锁':view==='luban'?'鲁班锁':current?.puzzle?'每日棋题':current?.endgame?'象棋残局':games[current.kind].name;window.scrollTo({top:0,behavior:'instant'});}
function navigate(view){cancelBot();if(current)saveCurrent();if(view==='puzzle'){openGame('chess',true);return;}showView(view);if(view==='records')renderRecords();}
document.querySelectorAll('[data-nav]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.nav)));
$('.brand').addEventListener('click',event=>{event.preventDefault();navigate('home');});
$('#back-home').addEventListener('click',()=>navigate('home'));
document.addEventListener('click',event=>{const play=event.target.closest('[data-play]');if(play){if(puzzleGames[play.dataset.play])openMind(play.dataset.play);else if(play.dataset.play==='rubik')openRubik();else if(play.dataset.play==='luban')openLuban();else openGame(play.dataset.play);}if(event.target.closest('[data-endgame]'))openEndgame();const filter=event.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===filter);x.setAttribute('aria-pressed',String(x===filter));});renderCards(filter.dataset.filter);}});

const mindRoom=new PuzzleRoom($('#mind-view'),()=>navigate('home'));
function openMind(kind){cancelBot();if(current){saveCurrent();current=null;}showView('mind');mindRoom.open(kind);}
function newState(kind,mode='ai',puzzle=false,endgame=null,aiLevel=store.aiLevels?.[kind]||'casual'){const state={kind,mode,puzzle,endgame,engine:endgame?endgameLib.createEndgame():boardRules[kind].create(puzzle),selected:null,thinking:false,startedAt:Date.now(),recordId:crypto.randomUUID(),archived:false};if(boardRules[kind].aiLevels)state.aiLevel=isAiLevel(aiLevel)?aiLevel:'casual';return state;}
function loadState(saved){if(!boardRules[saved.kind]||!['ai','local'].includes(saved.mode)||!Array.isArray(saved.moves)||saved.moves.length>1000)throw new Error('Invalid save');const state=newState(saved.kind,saved.mode,!!saved.puzzle);state.engine=boardRules[saved.kind].restore(saved.moves,!!saved.puzzle);if(boardRules[saved.kind].aiLevels)state.aiLevel=isAiLevel(saved.aiLevel)?saved.aiLevel:(store.aiLevels?.[saved.kind]||'casual');state.startedAt=saved.startedAt||Date.now();state.recordId=saved.recordId||crypto.randomUUID();state.archived=!!saved.archived;return state;}
function openGame(kind,puzzle=false,savedOverride=null){store.appearance.theme=boardThemes[store.appearance.gameThemes?.[kind]]?store.appearance.gameThemes[kind]:recommendedThemes[kind]||'classic';setThemeGroup(boardThemes[store.appearance.theme].group);cancelBot();if(current)saveCurrent();const saved=savedOverride||(!puzzle?store.saves[kind]:null);try{current=saved?loadState(saved):newState(kind,'ai',puzzle);}catch{current=newState(kind,'ai',puzzle);toast('存档无法读取，已为你开启新局。');}showView('play');renderGame();saveCurrent();scheduleBot();if(puzzle)toast(store.puzzleSolved?'你已经解出这道题，可以再挑战一次。':'白方先行，一步将杀。点击白后开始思考。');}
async function openEndgame(){cancelBot();if(current)saveCurrent();const active=session;try{endgameLib??=await import('./xiangqi-endgame.js');}catch{toast('残局资料暂时无法载入，请稍后重试。');return;}if(active!==session)return;store.appearance.theme=boardThemes[store.appearance.gameThemes?.xiangqi]?store.appearance.gameThemes.xiangqi:recommendedThemes.xiangqi||'classic';setThemeGroup(boardThemes[store.appearance.theme].group);current=newState('xiangqi','ai',false,newEndgame('study'));showView('play');renderGame();}
async function openRubik(){cancelBot();if(current){saveCurrent();current=null;}showView('unlock');if(!rubikPromise){rubikPromise=import('./rubik-3d.js').then(({Rubik3D})=>{rubikScene=new Rubik3D($('#rubik-stage'),state=>{const solved=state.solved;$('#rubik-move-count').textContent=state.moves+' 步';$('#rubik-status').textContent=solved?'六面归一 · 解锁成功':state.busy?'正在转动机关…':'让每一面回到自己的颜色。';$('#rubik-undo').disabled=!state.moves||state.busy;$('#rubik-shuffle').disabled=state.busy;document.querySelectorAll('[data-rubik-turn]').forEach(button=>button.disabled=state.busy);if(solved&&!$('#rubik-win').open&&!$('#unlock-view').hidden)$('#rubik-win').showModal();},bottom=>{const button=$('#rubik-bottom-view');button.setAttribute('aria-pressed',String(bottom));button.textContent=bottom?'返回常规视角 ↑':'查看底面 ↓';});rubikScene.newChallenge();return rubikScene;});}try{await rubikPromise;rubikScene.setActive(true);}catch{toast('3D 魔方暂时无法载入，请检查浏览器 WebGL 支持。');}}
async function openLuban(){cancelBot();if(current){saveCurrent();current=null;}showView('luban');if(!lubanPromise){lubanPromise=import('./luban-3d.js').then(({LubanLock3D})=>{lubanScene=new LubanLock3D($('#luban-stage'),state=>{const picked=state.parts.find(part=>part.id===state.selected);$('#luban-progress').textContent=state.solved?'六销已尽 · 机关解开':`第 ${Math.min(state.step+1,state.total)} / ${state.total} 销`;$('#luban-hint').textContent=state.message||(state.explode>0?'分解观察中 · 滑杆归零后继续解锁。':state.solved?'六根榫木已经依序抽出。':state.busy?'榫木正在滑出…':state.step===0?'找出最先松动的木销，试着抽动它。':'机关松开了一分，继续观察剩下的榫木。');$('#luban-picked').textContent=picked?`已选：${picked.name}`:'机关已解开';document.querySelectorAll('[data-luban-select]').forEach(button=>{const part=state.parts.find(x=>x.id===button.dataset.lubanSelect);button.disabled=state.busy||part?.removed;button.setAttribute('aria-pressed',String(button.dataset.lubanSelect===state.selected));button.classList.toggle('removed',!!part?.removed);});document.querySelectorAll('[data-luban-dir]').forEach(button=>button.disabled=state.busy||state.solved||state.explode>0);$('#luban-explode').disabled=state.busy;$('#luban-explode').value=Math.round(state.explode*100);$('#luban-explode-output').textContent=state.explode>0?Math.round(state.explode*100)+'%':'合拢';$('#luban-restart').disabled=state.busy;if(state.solved&&!$('#luban-win').open&&!$('#luban-view').hidden)$('#luban-win').showModal();});return lubanScene;});}try{await lubanPromise;lubanScene.setActive(true);}catch{toast('鲁班锁 3D 场景暂时无法载入，请检查浏览器 WebGL 支持。');}}
$('#daily-puzzle').addEventListener('click',()=>openGame('chess',true));
$('#unlock-back').addEventListener('click',()=>navigate('home'));
$('#rubik-shuffle').addEventListener('click',()=>rubikScene?.newChallenge());
$('#rubik-bottom-view').addEventListener('click',()=>rubikScene?.setBottomView(!rubikScene.bottomView));
$('#rubik-undo').addEventListener('click',()=>rubikScene?.undo());
