document.querySelectorAll('[data-luban-camera]').forEach(button=>button.addEventListener('click',()=>lubanScene?.setView(button.dataset.lubanCamera)));
$('#luban-explode').addEventListener('input',event=>lubanScene?.setExplode(Number(event.target.value)/100));
$('#luban-zoom').addEventListener('input',event=>{const zoom=Number(event.target.value)/100;lubanScene?.setZoom(zoom);$('#luban-zoom-output').textContent=zoom.toFixed(1)+'×';});
$('#luban-back').addEventListener('click',()=>navigate('home'));
$('#luban-help').addEventListener('click',()=>showDialog('鲁班锁 · 六销拆解','<p>这是受传统鲁班锁启发的 3D 顺序拆解机关。拖动木锁观察榫卯结构，点击木销名称或直接点选木件，再尝试六个方向。</p><p>可移动的木销会顺着方向滑出；被其他榫木咬住时会回弹。连续取出六销即可通关。点击「重置机关」可重新观察结构。</p>'));
document.querySelectorAll('[data-luban-select]').forEach(button=>button.addEventListener('click',()=>lubanScene?.select(button.dataset.lubanSelect)));
document.querySelectorAll('[data-luban-dir]').forEach(button=>button.addEventListener('click',()=>lubanScene?.tryMove(button.dataset.lubanDir)));
