function getMoves(){return boardRules[current.kind].moves(current.engine);}
function getTurn(){return boardRules[current.kind].turn(current.engine);}
function winner(){return boardRules[current.kind].winner(current.engine);}
function serialize(){return {kind:current.kind,mode:current.mode,puzzle:current.puzzle,aiLevel:current.aiLevel,moves:savedMoves(current.kind,current.engine),startedAt:current.startedAt,updatedAt:Date.now(),recordId:current.recordId,archived:current.archived,result:winner()};}
function saveCurrent(){if(!current||current.puzzle||current.endgame)return;const finished=winner()!==null;if(finished&&!current.archived){current.archived=true;store.archives.unshift(serialize());store.archives=store.archives.slice(0,30);}store.saves[current.kind]=serialize();persist();}
function colorName(player){return boardRules[current.kind].sides[player-1];}
function renderGame(){const g=games[current.kind],moves=getMoves(),turn=getTurn(),result=winner(),isAI=current.mode==='ai';
  const endgame=current.endgame,study=endgame?.view==='study',lesson=endgame&&endgameLib.ENDGAME;$('#play-title').textContent=current.puzzle?'一步，将杀。':lesson?lesson.name:g.name;$('#play-eyebrow').textContent=current.puzzle?'THE DAILY MOVE · NO. 001':lesson?lesson.english:g.english+' / PLAY AT YOUR OWN PACE';$('#game-subtitle').textContent=g.english+' · CHESS & CHEERS';$('#play-description').textContent=current.puzzle?'白方先行，找到一步将死黑王的走法。':lesson?lesson.summary:g.description;
  $('.mode-picker').hidden=current.puzzle||!!endgame;$('#endgame-entry').hidden=current.kind!=='xiangqi'||!!endgame||current.puzzle;document.querySelectorAll('[data-mode]').forEach(el=>{el.classList.toggle('selected',el.dataset.mode===current.mode);el.disabled=current.thinking;});
  const levels=boardRules[current.kind].aiLevels,aiLevel=current.aiLevel||'casual';$('#ai-level-panel').hidden=!(isAI&&!current.puzzle&&!endgame&&levels);document.querySelectorAll('[data-ai-level]').forEach(el=>{const selected=el.dataset.aiLevel===aiLevel;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));el.disabled=current.thinking;});$('#ai-level-note').textContent=levels?AI_LEVEL_NOTES[aiLevel]||'':'';
  $('#opponent-name').textContent=current.puzzle?'黑方 · 待解的棋局':isAI?'弈间棋友':'棋友 · '+colorName(2);$('#opponent-desc').textContent=current.puzzle?'一步将杀挑战':endgame?'将与双士 · 最顽强的防守':isAI?(levels?'电脑棋力 · '+(AI_LEVEL_NAMES[aiLevel]||'休闲'):'休闲电脑 · 陪你认真下一局'):'本地双人 · 共用一块棋盘';$('#opponent-color').textContent=colorName(2);$('#player-color').textContent=colorName(1)+' · 先行';
  $('#player-name').textContent=result!==null?'这局，值得回味':study?colorName(turn)+'走棋':current.thinking?'棋友正在思考…':turn===1?'你的回合':isAI?'等待棋友落子':colorName(2)+'的回合';$('#player-desc').textContent=current.puzzle?'点击白后，再选择目标格。':study?'主线讲解 · 用下方按钮逐步查看。':isAI?'你执'+colorName(1).replace('方','')+'，慢慢想，不着急。':'与你的朋友，轮流落子。';
  let status=result===null?(current.thinking?'棋友正在思考…':colorName(turn)+'落子'):result===0?'平局，也是一场好棋。':colorName(result)+'获胜';let hint=g.instruction;
  if(current.puzzle&&result!==null){status='漂亮，一步将杀！';hint='你找到了属于这局的好棋。';}
  else if(endgame&&result!==null)hint=current.engine.reason+(study?' · 主线到此结束。':' · 可以重新开局，再试一次。');
  else if(study)hint='主线第 '+endgame.step+' / '+lesson.line.length+' 手';
  else if(result!==null)hint=(current.engine.reason?current.engine.reason+' · ':'')+'可以导出棋谱，或再开一局。';
  else if(current.kind==='xiangqi'&&current.engine.isInCheck())hint='将军！请先解将，保护你的'+(turn===1?'帅':'将')+'。';
  else if(current.kind==='go'){const {phase,captures}=current.engine;if(phase==='scoring'){status='数子确认';hint='双方都停了一手，请确认面板里的结果。';}else hint=`黑提 ${captures[1]} · 白提 ${captures[2]} · ${moves.at(-1)?.pass?colorName(moves.at(-1).player)+'停了一手，再停一手就进入数子。':'点击交叉点落子。'}`;}
  else if(current.kind==='tiaoqi')hint=`到位 红 ${current.engine.progress(1)}/10 · 蓝 ${current.engine.progress(2)}/10 · ${g.instruction}`;
  else if(current.kind==='reversi'){const [b,w]=current.engine.score();hint=`黑 ${b} : ${w} 白 · ${moves.at(-1)?.pass?'对方无合法落点，自动跳过。':'落在小圆点处，翻转对方棋子。'}`;}
  else if(current.kind==='chess'&&current.engine.isCheck())hint='将军！请保护你的国王。';
  else if(current.puzzle)hint='白方先行 · 找到一步将死黑王的走法';
  $('#game-status').textContent=status;$('#game-hint').textContent=hint;$('#move-count').textContent=moves.length+' 手';$('#undo-button').disabled=!moves.length||current.thinking;$('#export-button').disabled=!moves.length;$('#export-button').hidden=!!endgame;$('.game-actions').hidden=study;$('.board-zoom-control').hidden=!!endgame;
  $('.autosave-note').innerHTML=icon('check')+(endgame?'残局研习 · 不写入棋谱存档':current.puzzle?'每日棋题 · 完成状态保存在此浏览器':storageAvailable?'自动保存进度，随时回来接着下。':'当前无法自动保存，请导出棋谱。');
  $('#move-history').innerHTML=moves.length?Array.from({length:Math.ceil(moves.length/2)},(_,i)=>`<div class="move-row"><span>${i+1}.</span><span>${moves[2*i].label}</span><span>${moves[2*i+1]?.label||'—'}</span></div>`).join(''):'<div class="empty-moves">故事，从你的第一步开始。</div>';
  $('#move-history').scrollTop=$('#move-history').scrollHeight;renderBoard();renderEndgame();renderGoPanel();applyAppearance();
}
function goMarks(){const engine=current.engine;if(engine.phase==='play'){current.goDead=null;return null;}current.goDead=engine.phase==='over'?new Set(engine.finalDead.map(([r,c])=>r+','+c)):current.goDead||new Set(estimateDead(engine).map(([r,c])=>r+','+c));return {dead:current.goDead,score:engine.score([...current.goDead].map(key=>key.split(',').map(Number)))};}
function goSceneBoard(){const marks=goMarks();if(!marks)return current.engine.board;return current.engine.board.map((row,r)=>row.map((value,c)=>value?(marks.dead.has(r+','+c)?{type:'dead',color:value}:value):marks.score.territory[r][c]?{type:'terr',color:marks.score.territory[r][c]}:0));}
function renderGoPanel(){const panel=$('#go-panel'),isGo=current.kind==='go';panel.hidden=!isGo;if(!isGo)return;const engine=current.engine,marks=goMarks(),scoring=engine.phase==='scoring',over=engine.phase==='over',local=current.mode==='local';$('#go-pass').hidden=engine.phase!=='play';$('#go-pass').disabled=current.thinking||(!local&&getTurn()===2);$('#go-finish').hidden=$('#go-resume').hidden=!scoring;$('#go-resume').disabled=current.thinking;$('#go-score').textContent=marks?`黑 ${marks.score.black} : 白 ${marks.score.white} + 贴 ${GO_KOMI}`:'';$('#go-score').hidden=!marks;$('#go-note').textContent=over?'':scoring?(local?'半透明的棋子是判为死子的棋，点一块棋可以改判。两人都同意后确认结果。':'半透明的棋子是电脑判为死子的棋。不同意就继续对局，把棋走清楚；数子法下多走几手不吃亏。'):'一盘棋下完后双方各停一手。收完单官再停，空着的中立点不计入任何一方。';if(scoring)$('#player-name').textContent='数子确认';}
function newEndgame(view){return {view,step:0,note:null,hint:null,showMoves:false};}
function endgameDistanceText(distance){return distance===null?'红方已无胜势':distance===0?'黑方已无棋可走':`红方还需走 ${distance} 步取胜`;}
function renderEndgame(){const panel=$('#endgame-panel'),state=current.endgame;panel.hidden=!state;if(!state)return;const lesson=endgameLib.ENDGAME,study=state.view==='study',total=lesson.line.length,engine=current.engine,over=winner()!==null,analysis=endgameLib.analyze(engine);
  panel.querySelectorAll('[data-endgame-view]').forEach(button=>{const selected=button.dataset.endgameView===state.view;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));button.disabled=current.thinking;});
  const entry=study?(state.step?lesson.line[state.step-1]:{title:lesson.intro[0],note:lesson.intro[1]}):null;$('#endgame-label').textContent=study?(state.step?`第 ${state.step} / ${total} 手`:'开始之前'):'你执红 · 电脑防守';$('#endgame-title').textContent=study?entry.title:state.note?.title||'轮到你了';$('#endgame-note').textContent=study?entry.note:state.note?.text||'点击红方棋子走棋。每走一步，这里都会告诉你是否仍保持胜势。';$('#endgame-note').closest('.endgame-note').dataset.tone=study?'':state.note?.tone||'';
  $('#endgame-ideas').hidden=!(study&&state.step===total);$('#endgame-ideas').innerHTML=lesson.ideas.map(idea=>`<li>${idea}</li>`).join('');
  $('.endgame-steps').hidden=!study;panel.querySelectorAll('[data-endgame-step]').forEach(button=>{const forward=['next','last'].includes(button.dataset.endgameStep);button.disabled=forward?state.step===total:state.step===0;});
  $('#endgame-hint').hidden=study;$('#endgame-hint').disabled=over||current.thinking||engine.turn!==1;
  $('#endgame-eval').textContent=over?engine.reason:endgameDistanceText(analysis.distance);
  $('#endgame-toggle').hidden=over;$('#endgame-toggle').textContent=state.showMoves?'收起着法分析':`着法分析 · ${analysis.moves.length} 种走法`;$('#endgame-toggle').setAttribute('aria-expanded',String(state.showMoves));
  const list=$('#endgame-moves');list.hidden=over||!state.showMoves;list.innerHTML=over||!state.showMoves?'':analysis.moves.map((move,i)=>`<li class="${i===0||move.remaining===analysis.moves[0].remaining?'best':''}"><span>${move.label}</span><small>${move.remaining===null?(analysis.side===1?'车被吃，胜势消失':'吃掉红车，守和'):move.remaining===0?'立即取胜':'红方还需 '+move.remaining+' 步'}</small></li>`).join('');
}
function reviewEndgameMove(played){const state=current.endgame;if(played.player!==1)return;state.hint=null;const before=state.distance,result=winner();if(result===1){state.note={tone:'good',title:'漂亮，'+current.engine.reason+'！',text:'这就是单车胜双士的收束。可以切回「主线讲解」对照思路。'};return;}if(result!==null){state.note={tone:'bad',title:'这局走成了和棋',text:current.engine.reason+'。悔棋后换一条路，别让局面循环。'};return;}const after=endgameLib.blackDistance(current.engine);if(after===null)state.note={tone:'bad',title:'这一步丢了车',text:'黑方可以直接吃车，胜势就没了。悔棋再想想。'};else if(after===before-1)state.note={tone:'good',title:'好棋，这是最快的走法',text:endgameDistanceText(after)+'。'};else state.note={tone:'warn',title:'仍然必胜，但不是最快',text:`这步之后${endgameDistanceText(after)}，最快的走法只需再走 ${before-1} 步。`};}
function syncEndgame(){const state=current?.endgame;if(state&&current.engine.turn===1&&current.engine.winner===null)state.distance=endgameLib.redDistance(current.engine);}
function setEndgameStep(target){const state=current.endgame,line=endgameLib.ENDGAME.line,step=Math.max(0,Math.min(line.length,target));if(step===state.step)return;stopEffects();const forward=step===state.step+1;let played=null;if(step<state.step)for(let i=state.step;i>step;i--)current.engine.undo();else for(let i=state.step;i<step;i++){const m=line[i];played=current.engine.move(m.fr,m.fc,m.r,m.c);}state.step=step;current.selected=null;renderGame();if(forward&&played){const event=moveEvent('xiangqi',played);playSound(event.capture?'capture':'move');effects.move(event,store.appearance.view==='3d');scene3d?.move(event,!effects.motion);}}
function setEndgameView(view){const state=current?.endgame;if(!state||state.view===view)return;cancelBot();if(view==='study'){const fresh=newEndgame('study');current=newState('xiangqi','ai',false,fresh);}else{state.view='practice';state.note=null;state.hint=null;if(winner()!==null){current=newState('xiangqi','ai',false,newEndgame('practice'));}syncEndgame();}renderGame();scheduleBot();}
function syncBoardZoom(){const zoom=current?.endgame?1:store.appearance.zoom,stage=$('#board-stage'),section=stage.closest('.board-section'),stack=zoom>=1.25&&window.innerWidth>900;stage.dataset.zoomed=String(stack);stage.style.width=`${Math.round(zoom*(window.innerWidth<=900?100:stack?60:100))}%`;section.classList.toggle('board-zoomed',stack);$('#board-zoom').value=Math.round(zoom*100);$('#zoom-output').textContent=zoom.toFixed(2).replace(/\.?0+$/,'')+'×';}
function setThemeGroup(group){document.querySelectorAll('[data-theme-family]').forEach(b=>b.hidden=b.dataset.themeFamily!==group);document.querySelectorAll('[data-theme-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeGroup===group)));}
document.querySelectorAll('[data-theme-group]').forEach(b=>b.addEventListener('click',()=>setThemeGroup(b.dataset.themeGroup)));
$('#theme-recommend').addEventListener('click',()=>{if(!current)return;store.appearance.theme=recommendedThemes[current.kind]||'classic';store.appearance.gameThemes??={};delete store.appearance.gameThemes[current.kind];setThemeGroup(boardThemes[store.appearance.theme].group);applyAppearance();persist();});
function applyAppearance(){const {view,theme,angle}=store.appearance,frame=$('#board-frame');frame.dataset.view='2d';frame.dataset.theme=theme;const palette=boardThemes[theme]||boardThemes.classic;frame.style.setProperty('--surface-dark',palette.dark);frame.style.setProperty('--surface-light',palette.light);frame.style.setProperty('--surface-line',palette.line);$('#theme-note').textContent=palette.name+' · '+palette.note;$('#board-stage').dataset.view=view;$('#board-3d').hidden=view!=='3d';$('.scene-badge').hidden=view!=='3d';document.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));document.querySelectorAll('[data-theme]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.theme===theme)));$('.rotation-control').hidden=view!=='3d';$('#board-angle').value=angle;$('#angle-output').textContent=angle+'°';syncBoardZoom();if(view==='3d')ensureScene();else scene3d?.setActive(false);}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{store.appearance.view=button.dataset.view;applyAppearance();persist();}));
document.querySelectorAll('[data-theme]').forEach(button=>button.addEventListener('click',()=>{store.appearance.theme=button.dataset.theme;store.appearance.gameThemes??={};if(current)store.appearance.gameThemes[current.kind]=button.dataset.theme;applyAppearance();persist();}));
$('#board-zoom').addEventListener('input',event=>{store.appearance.zoom=Number(event.target.value)/100;syncBoardZoom();persist();});
