const pieceNames={p:'兵',r:'车',n:'马',b:'象',q:'后',k:'王'};
function renderBoard(){const board=$('#board'),kind=current.kind;$('#board-stage').dataset.kind=kind;$('#board-frame').className='board-frame '+kind;board.className='game-board '+(kind==='tictactoe'?'ttt':kind)+'-board';const last=getMoves().at(-1);const locked=current.thinking||current.endgame?.view==='study'||winner()!==null||(current.mode==='ai'&&getTurn()===2&&!current.puzzle);
  if(kind==='xiangqi'){
    const selected=current.selected?current.selected.split(',').map(Number):null,legal=selected?current.engine.legalMoves().filter(m=>m.fr===selected[0]&&m.fc===selected[1]):[];
    board.innerHTML=current.engine.board.map((row,r)=>row.map((piece,c)=>{const isSelected=current.selected===r+','+c,isLegal=legal.some(m=>m.r===r&&m.c===c),isLast=last&&((last.r===r&&last.c===c)||(last.fr===r&&last.fc===c));return `<button class="board-cell ${isSelected?'selected':''} ${isLegal?'legal':''} ${isLast?'last-move':''}" data-r="${r}" data-c="${c}" ${locked?'disabled':''} aria-label="${xiangqiCoordinate(r,c)}${piece?' '+(piece.color===1?'红':'黑')+XIANGQI_NAMES[piece.color][piece.type]:' 空位'}${isLegal?' 可落子':''}" aria-pressed="${isSelected}">${piece?`<span class="xiangqi-piece ${piece.color===1?'red':'black'}">${XIANGQI_NAMES[piece.color][piece.type]}</span>`:''}</button>`;}).join('')).join('');
  }else if(kind==='go'){
    const marks=goMarks(),playing=current.engine.phase==='play';
    board.innerHTML=current.engine.board.map((row,r)=>row.map((value,c)=>{const isLast=last&&last.r===r&&last.c===c,star=GO_STARS.some(([a,b])=>a===r&&b===c),dead=marks?.dead.has(r+','+c),owner=!value&&marks?marks.score.territory[r][c]:0,edges=`${c===0?'go-l':''} ${c===GO_SIZE-1?'go-r':''} ${r===0?'go-t':''} ${r===GO_SIZE-1?'go-b':''}`,canTap=playing?!value:current.mode==='local'&&!!value;return `<button class="board-cell ${edges} ${isLast?'last-move':''} ${star?'star':''} ${owner?'go-terr go-terr-'+owner:''}" data-r="${r}" data-c="${c}" ${locked||!canTap?'disabled':''} aria-label="${goCoordinate(r,c)} ${value?colorName(value)+(dead?' 死子':''):owner?colorName(owner)+'地盘':'空位'}">${value?`<span class="stone ${value===1?'black':'white'} ${dead?'dead':''}"></span>`:''}</button>`;}).join('')).join('');
  }else if(kind==='jungle'){
    const selected=current.selected?current.selected.split(',').map(Number):null,legal=selected?current.engine.legalMoves().filter(m=>m.fr===selected[0]&&m.fc===selected[1]):[];
    board.innerHTML=current.engine.board.map((row,r)=>row.map((piece,c)=>{const isSelected=current.selected===r+','+c,isLegal=legal.some(m=>m.r===r&&m.c===c),isLast=last&&((last.r===r&&last.c===c)||(last.fr===r&&last.fc===c)),water=isWater(r,c),trap=trapOwner(r,c),den=denOwner(r,c),place=water?'河':den?colorName(den)+'兽穴':trap?colorName(trap)+'陷阱':'',animal=piece&&JUNGLE_ANIMALS[piece.type];return `<button class="board-cell ${water?'water':''} ${trap?'trap':''} ${den?'den':''} ${isSelected?'selected':''} ${isLegal?'legal':''} ${isLast?'last-move':''}" data-r="${r}" data-c="${c}" ${locked?'disabled':''} aria-label="${jungleCoordinate(r,c)} ${place}${piece?' '+colorName(piece.color)+animal.name:place?'':' 空位'}${isLegal?' 可落子':''}" aria-pressed="${isSelected}">${piece?`<span class="jungle-piece ${piece.color===1?'red':'blue'}">${animal.name}<small>${animal.rank}</small></span>`:trap?'<i class="jungle-mark">陷</i>':den?'<i class="jungle-mark den-mark">穴</i>':''}</button>`;}).join('')).join('');
  }else if(kind==='tiaoqi'){
    const selected=current.selected?current.selected.split(',').map(Number):null,legal=selected?current.engine.destinations(...selected):[],height=16*Math.sqrt(3)/2+1.4;
    board.innerHTML=`<svg class="tiaoqi-lines" viewBox="-7 ${-height/2} 14 ${height}" aria-hidden="true">${TIAOQI_EDGES.map(([a,b,c,d])=>{const p=tiaoqiXY(a,b),q=tiaoqiXY(c,d);return `<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"/>`;}).join('')}</svg>`+TIAOQI_HOLES.map(([r,c])=>{const value=current.engine.board[r][c],{x,y}=tiaoqiXY(r,c),isSelected=current.selected===r+','+c,isLegal=legal.some(m=>m.r===r&&m.c===c),isLast=last?.path.some(([a,b])=>a===r&&b===c),won=current.engine.winning.some(([a,b])=>a===r&&b===c),home=homeOwner(r,c);return `<button class="board-cell ${home?'home-'+home:''} ${isSelected?'selected':''} ${isLegal?'legal':''} ${isLast?'last-move':''} ${won?'winning':''}" style="left:${(x+7)/14*100}%;top:${(y+height/2)/height*100}%" data-r="${r}" data-c="${c}" ${locked?'disabled':''} aria-label="${tiaoqiCoordinate(r,c)} ${value?colorName(value):'空位'}${isLegal?' 可落子':''}" aria-pressed="${isSelected}">${value?`<span class="stone ${value===1?'red':'blue'}"></span>`:''}</button>`;}).join('');
  }else if(kind==='connect4'){
    const landing=locked?[]:current.engine.legalMoves();
    board.innerHTML=current.engine.board.map((row,r)=>row.map((value,c)=>{const isLast=last&&last.r===r&&last.c===c,isLegal=landing.some(m=>m.r===r&&m.c===c),won=current.engine.winning.some(([wr,wc])=>wr===r&&wc===c),full=current.engine.heights[c]>=6;return `<button class="board-cell ${isLast?'last-move':''} ${isLegal?'legal':''} ${won?'winning':''}" data-r="${r}" data-c="${c}" ${locked||full?'disabled':''} aria-label="${connect4Coordinate(r,c)} ${value?colorName(value):'空位'}${isLegal?' 可落子':''}">${value?`<span class="stone ${value===1?'red':'gold'}"></span>`:''}</button>`;}).join('')).join('');
  }else if(kind==='chess'){
    const legal=current.selected?current.engine.moves({square:current.selected,verbose:true}).map(m=>m.to):[];
    board.innerHTML=current.engine.board().map((row,r)=>row.map((piece,c)=>{const square='abcdefgh'[c]+(8-r),dark=(r+c)%2;return `<button class="board-cell ${dark?'dark':''} ${current.selected===square?'selected':''} ${legal.includes(square)?'legal':''} ${last&&(last.to===square||last.from===square)?'last-move':''}" data-square="${square}" ${locked?'disabled':''} aria-label="${square}${piece?' '+(piece.color==='w'?'白':'黑')+pieceNames[piece.type]:''}${legal.includes(square)?' 可落子':''}" aria-pressed="${current.selected===square}">${piece?pieceSVG(piece.type,piece.color):''}${c===0||r===7?`<span class="square-label">${c===0?8-r:''}${r===7?'abcdefgh'[c]:''}</span>`:''}</button>`;}).join('')).join('');
  }else{
    const legal=kind==='reversi'?current.engine.legalMoves().map(m=>m.r+','+m.c):[];
    board.innerHTML=current.engine.board.map((row,r)=>row.map((value,c)=>{const isLast=last&&last.r===r&&last.c===c;const star=kind==='gomoku'&&[3,7,11].includes(r)&&[3,7,11].includes(c);const content=kind==='tictactoe'?(value===1?'×':value===2?'○':''):value?`<span class="stone ${value===1?'black':'white'}"></span>`:'';const winning=current.engine.winning.some(([wr,wc])=>wr===r&&wc===c);return `<button class="board-cell ${isLast?'last-move':''} ${star?'star':''} ${legal.includes(r+','+c)?'legal':''} ${value===2?'o':''} ${winning?'winning':''}" data-r="${r}" data-c="${c}" ${locked||value?'disabled':''} aria-label="${coordinate(r,c,current.engine.size)} ${value?colorName(value):'空位'}${legal.includes(r+','+c)?' 可落子':''}">${content}</button>`;}).join('')).join('');
  }
  syncScene();
}
async function promotionChoice(){return new Promise(resolve=>{promotionResolve=resolve;showDialog('兵抵达彼岸，选择升变。','<p>选择你希望升变的棋子：</p><div style="display:flex;gap:10px">'+[['q','后'],['r','车'],['b','象'],['n','马']].map(([type,name])=>`<button class="button secondary" data-promotion="${type}">${name}</button>`).join('')+'</div>','取消');$('#dialog-body').querySelectorAll('[data-promotion]').forEach(button=>button.addEventListener('click',()=>{promotionResolve=null;resolve(button.dataset.promotion);closeDialog();}));});}
$('#board').addEventListener('click',async event=>{
  const cell=event.target.closest('.board-cell');if(!cell||cell.disabled||!current||current.thinking||winner()!==null)return;
  if(current.kind==='go'&&current.engine.phase==='scoring'){
    const {stones}=current.engine.group(Number(cell.dataset.r),Number(cell.dataset.c)),keys=stones.map(([r,c])=>r+','+c),dead=current.goDead.has(keys[0]);keys.forEach(key=>dead?current.goDead.delete(key):current.goDead.add(key));renderBoard();renderGoPanel();
  }else if(current.kind==='xiangqi'||current.kind==='jungle'){
    const r=Number(cell.dataset.r),c=Number(cell.dataset.c),piece=current.engine.board[r][c],selected=current.selected?current.selected.split(',').map(Number):null;
    const played=selected?current.engine.move(selected[0],selected[1],r,c):false;
    if(played){current.selected=null;afterMove(played);}else if(piece?.color===current.engine.turn){current.selected=r+','+c;renderBoard();}else{current.selected=null;renderBoard();}
  }else if(current.kind==='tiaoqi'){
    const r=Number(cell.dataset.r),c=Number(cell.dataset.c),selected=current.selected?current.selected.split(',').map(Number):null;
    const played=selected?current.engine.move(selected[0],selected[1],r,c):false;
    if(played){current.selected=null;afterMove(played);}else{current.selected=current.engine.board[r][c]===current.engine.turn&&current.selected!==r+','+c?r+','+c:null;renderBoard();}
  }else if(current.kind==='chess'){
    const square=cell.dataset.square,piece=current.engine.get(square),turn=current.engine.turn();
    const legal=current.selected?current.engine.moves({square:current.selected,verbose:true}).filter(m=>m.to===square):[];
    if(legal.length){let promotion;const activeSession=session;if(legal.some(m=>m.promotion)){promotion=await promotionChoice();if(!promotion||session!==activeSession)return;}const played=current.engine.move({from:current.selected,to:square,...(promotion?{promotion}:{})});current.selected=null;
      if(current.puzzle&&!current.engine.isCheckmate()){current.engine.undo();renderGame();toast('这一步还没有将杀。再看看黑王能逃向哪里？');return;}
      if(current.puzzle){store.puzzleSolved=true;persist();toast('解题成功！将思考的乐趣，留给下一局。');}
      afterMove(played);
    }else if(piece&&piece.color===turn){current.selected=square;renderBoard();}else{current.selected=null;renderBoard();}
  }else{const played=current.engine.move(Number(cell.dataset.r),Number(cell.dataset.c));if(played)afterMove(played);else toast(current.engine.illegalText?.(Number(cell.dataset.r),Number(cell.dataset.c))||'这里不能落子，请选择标记的空位。');}
});
function afterMove(played){if(current.endgame){reviewEndgameMove(played);syncEndgame();}const event=moveEvent(current.kind,played);playSound(event?.capture?'capture':'move');if(played?.pass)toast(colorName(played.player)+'停了一手。');saveCurrent();renderGame();scheduleBot();effects.move(event,store.appearance.view==='3d');if(event&&store.appearance.view==='3d')scene3d?.move(event,!effects.motion);if(winner()!==null){const active=session;victoryTimer=setTimeout(()=>{if(active===session&&!$('#play-view').hidden)showVictory();},effects.motion?750:0);}}
function scheduleBot(){if(!current||current.engine.phase==='scoring'||current.puzzle||current.endgame?.view==='study'||current.mode!=='ai'||getTurn()!==2||winner()!==null)return;current.thinking=true;renderGame();const activeSession=session,state=current;botTimer=setTimeout(()=>{if(session!==activeSession||$('#play-view').hidden||current!==state)return;const rules=boardRules[state.kind],aiOptions=rules.aiLevels?{level:state.aiLevel||'casual'}:undefined,move=state.endgame?endgameLib.chooseDefense(state.engine):rules.choose(state.engine,aiOptions);if(session!==activeSession||$('#play-view').hidden||current!==state){state.thinking=false;return;}let played;if(move)played=rules.apply(state.engine,move);state.thinking=false;afterMove(played);},700);}
$('#undo-button').addEventListener('click',()=>{if(!current||current.thinking)return;cancelBot();const engine=current.engine;if(current.kind==='chess')engine.undo();else engine.undo();if(current.mode==='ai'&&!current.puzzle)while(getMoves().length&&getTurn()===2)engine.undo();current.selected=null;current.archived=false;current.recordId=crypto.randomUUID();if(current.endgame){current.endgame.note=null;current.endgame.hint=null;syncEndgame();}saveCurrent();renderGame();toast('已回到你落子之前。');});
function replaceGame(mode=current.mode){cancelBot();const {kind,puzzle,endgame,aiLevel}=current;current=newState(kind,mode,puzzle,endgame&&newEndgame(endgame.view),aiLevel);syncEndgame();saveCurrent();renderGame();}
$('#restart-button').addEventListener('click',()=>{if(!getMoves().length){toast('新棋局已经准备好了。');return;}showDialog('再开一局？','<p>本局进行中的落子记录会被新的棋局替换。你可以先取消并导出棋谱。</p>','重新开局',()=>replaceGame());});
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{const mode=button.dataset.mode;if(!current||current.mode===mode)return;const change=()=>replaceGame(mode);if(getMoves().length)showDialog('切换对弈模式？','<p>切换模式会开启新棋局。本局如需留存，请先取消并导出棋谱。</p>','切换并开局',change);else change();}));
document.querySelectorAll('[data-ai-level]').forEach(button=>button.addEventListener('click',()=>{const level=button.dataset.aiLevel;if(!current||current.mode!=='ai'||current.thinking||!boardRules[current.kind].aiLevels||level===current.aiLevel)return;if(!isAiLevel(level))return;current.aiLevel=level;store.aiLevels[current.kind]=level;saveCurrent();renderGame();toast(`对手棋力已调整为「${AI_LEVEL_NAMES[level]}」。`);}));
$('#rules-button').addEventListener('click',()=>showDialog(current.puzzle?'每日棋题 · 一步将杀':current.endgame?endgameLib.ENDGAME.name+' · 研习说明':games[current.kind].name+' · 玩法说明',`<p>${current.puzzle?'白方先行。点击白后，再点击目标格；找到一步将死黑王的走法，即可解题成功。':current.endgame?endgameLib.ENDGAME.rules:games[current.kind].rules}</p><p>点击「悔棋」可回到你落子之前。人机模式下，你始终执先手。</p>`));
$('#endgame-entry').addEventListener('click',openEndgame);
$('#go-pass').addEventListener('click',()=>{if(current?.kind!=='go'||current.thinking)return;const played=current.engine.pass();if(played)afterMove(played);});
$('#go-finish').addEventListener('click',()=>{if(current?.kind!=='go'||!current.goDead)return;const played=current.engine.finish([...current.goDead].map(key=>key.split(',').map(Number)));if(played)afterMove(played);});
$('#go-resume').addEventListener('click',()=>{if(current?.kind!=='go'||current.engine.phase!=='scoring')return;current.engine.undo();current.engine.undo();saveCurrent();renderGame();scheduleBot();toast('回到停一手之前，继续把棋走清楚。');});
document.querySelectorAll('[data-endgame-view]').forEach(button=>button.addEventListener('click',()=>setEndgameView(button.dataset.endgameView)));
document.querySelectorAll('[data-endgame-step]').forEach(button=>button.addEventListener('click',()=>{const step=current.endgame.step;setEndgameStep({first:0,prev:step-1,next:step+1,last:Infinity}[button.dataset.endgameStep]);}));
$('#endgame-toggle').addEventListener('click',()=>{current.endgame.showMoves=!current.endgame.showMoves;renderEndgame();});
$('#endgame-hint').addEventListener('click',()=>{const best=endgameLib.analyze(current.engine).moves[0];if(!best)return;current.selected=best.fr+','+best.fc;current.endgame.note={tone:'',title:'提示',text:`试试 ${best.label}。`};renderBoard();renderEndgame();});
document.addEventListener('keydown',event=>{if(current?.endgame?.view!=='study'||$('#play-view').hidden||document.querySelector('dialog[open]')||event.target.matches('input,select,textarea'))return;if(event.key==='ArrowRight'){event.preventDefault();setEndgameStep(current.endgame.step+1);}else if(event.key==='ArrowLeft'){event.preventDefault();setEndgameStep(current.endgame.step-1);}});
$('#export-button').addEventListener('click',()=>{if(!current||!getMoves().length)return;const g=games[current.kind];const content=current.kind==='chess'?current.engine.pgn():JSON.stringify({title:g.name,version:1,...serialize()},null,2);const blob=new Blob([content],{type:current.kind==='chess'?'application/x-chess-pgn':'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`chess-cheers-${current.kind}-${new Date().toISOString().slice(0,10)}.${current.kind==='chess'?'pgn':'json'}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('棋谱已导出，留住这一局的思考。');});
function renderRecords(){const records=[...Object.values(store.saves).filter(x=>x.moves?.length&&x.result===null),...store.archives].filter(x=>boardRules[x.kind]);const list=$('#records-list');if(!records.length){list.innerHTML=`<div class="records-empty"><span class="eyebrow">THE FIRST MOVE IS YOURS</span><h2>这里，等待你的第一局。</h2><p>开一局棋，进度与完成的棋谱会出现在这里。</p><button class="button primary" data-play="gomoku">去下一局 ${icon('arrow')}</button></div>`;return;}list.innerHTML=records.map((record,index)=>{const date=new Date(record.updatedAt).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});const result=record.result===null?'进行中':record.result===0?'平局':boardRules[record.kind].sides[record.result-1]+'获胜';return `<div class="record-card"><span class="record-symbol">${boardRules[record.kind].symbol}</span><div><h3>${games[record.kind].name}</h3><p>${date} · ${record.mode==='ai'?('人机对弈'+(boardRules[record.kind].aiLevels?' · '+(AI_LEVEL_NAMES[record.aiLevel]||'休闲'):'')):'本地双人'} · ${record.moves.length} 手</p></div><div class="record-right"><span>${result}</span><button class="button secondary" data-record="${index}">${record.result===null?'继续对弈':'查看终局'} ${icon('arrow')}</button></div></div>`;}).join('');list.querySelectorAll('[data-record]').forEach(button=>button.addEventListener('click',()=>{const record=records[Number(button.dataset.record)];openGame(record.kind,false,record);}));}
window.addEventListener('beforeunload',()=>{if(current)saveCurrent();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(current)saveCurrent();stopEffects();scene3d?.setActive(false);rubikScene?.setActive(false);lubanScene?.setActive(false);}else{if(current&&store.appearance.view==='3d'&&!$('#play-view').hidden)scene3d?.setActive(true);if(!$('#unlock-view').hidden)rubikScene?.setActive(true);if(!$('#luban-view').hidden)lubanScene?.setActive(true);}});
$('#today-date').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
$('#hero-board').innerHTML=heroArt();$('#puzzle-mini').innerHTML=Array.from({length:16},(_,i)=>`<span class="${(Math.floor(i/4)+i%4)%2?'dark':''}">${({3:['k','b'],5:['q','w'],10:['k','w']})[i]?pieceSVG(...({3:['k','b'],5:['q','w'],10:['k','w']})[i]):''}</span>`).join('');
